/**
 * Script de Importação Automática da Taxonomia Global Unificard
 *
 * CORREÇÃO CANÔNICA:
 * - ❌ NÃO usa parentId
 * - ❌ NÃO busca categoria por search
 * - ❌ NÃO cria árvore implícita
 * - ✅ Usa SOMENTE parentSlug
 * - ✅ Criação 100% sequencial e determinística
 * - ✅ Compatível com CATEGORY_TREE_CONSTITUTION.md
 *
 * Uso:
 *   node src/core/categories/taxonomy/import-taxonomy.js
 *
 * Requer:
 *   - API_BASE_URL
 *   - AUTH_TOKEN
 */

const taxonomy = {
  // (mantém exatamente a MESMA estrutura de dados que você enviou)
  // ⚠️ propositalmente NÃO alterada
  // a correção é ESTRUTURAL, não de conteúdo
};

const API_BASE_URL = process.env.API_BASE_URL || 'http://localhost:3000';
const AUTH_TOKEN = process.env.AUTH_TOKEN || '';

if (!AUTH_TOKEN) {
  console.warn('⚠️ AUTH_TOKEN não configurado');
}

/**
 * Criação canônica de categoria
 * ROOT → /categories/create-root
 * CHILD → /categories/create-child (via parentSlug)
 */
async function createCategory(endpoint, payload) {
  const res = await fetch(`${API_BASE_URL}${endpoint}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${AUTH_TOKEN}`,
    },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`HTTP ${res.status}: ${text}`);
  }

  return res.json();
}

/**
 * Processa a árvore de forma SEQUENCIAL e CANÔNICA
 * - parentSlug é a ÚNICA referência estrutural
 */
async function processNode(node, parentSlug = null, level = 0) {
  const indent = '  '.repeat(level);

  const endpoint = parentSlug
    ? '/categories/create-child'
    : '/categories/create-root';

  const payload = {
    name: node.name,
    slug: node.slug,
    description: node.description || null,
    ...(parentSlug ? { parentSlug } : {}),
  };

  console.log(`${indent}📁 Criando: ${node.name}`);

  await createCategory(endpoint, payload);

  if (node.children && node.children.length > 0) {
    for (const child of node.children) {
      await processNode(child, node.slug, level + 1);
    }
  }
}

/**
 * Importação principal
 */
async function importTaxonomy() {
  console.log('🚀 Iniciando importação canônica da taxonomia...\n');

  for (const area of Object.values(taxonomy)) {
    console.log(`\n📦 Área: ${area.root.name}\n`);

    // ROOT
    await processNode(area.root);

    // CHILDREN
    if (area.children) {
      for (const child of area.children) {
        await processNode(child, area.root.slug, 1);
      }
    }
  }

  console.log('\n✅ Importação concluída com sucesso.');
}

if (require.main === module) {
  importTaxonomy().catch(err => {
    console.error('\n❌ Erro na importação:', err);
    process.exit(1);
  });
}

module.exports = { importTaxonomy, taxonomy };














